<PageTitle>Shipments</PageTitle>

<h1>Shipments</h1>

<button class="btn btn-primary mb-3" @onclick="ToggleForm">
    @(showForm ? "Cancel" : "New Shipment")
</button>

@if (showForm)
{
    <div class="card mb-3">
        <div class="card-body">
            <h5 class="card-title">Create Shipment</h5>
            <div class="row g-2">
                <div class="col-md-4">
                    <input class="form-control" placeholder="Tracking Number" @bind="newShipment.TrackingNumber" />
                </div>
                <div class="col-md-4">
                    <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-4">
                    <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-4">
                    <input class="form-control" placeholder="Customer Email" @bind="newShipment.CustomerEmail" />
                </div>
                <div class="col-md-4">
                    <input class="form-control" type="date" @bind="newShipment.ShippedDate" />
                </div>
                <div class="col-md-4">
                    <input class="form-control" type="date" @bind="newShipment.EstimatedDelivery" />
                </div>
                <div class="col-12">
                    <input class="form-control" placeholder="Description" @bind="newShipment.Description" />
                </div>
                <div class="col-12">
                    <button class="btn btn-success" @onclick="CreateShipment">Create</button>
                </div>
            </div>
        </div>
    </div>
}

@if (shipments is null)
{
    <p>Loading...</p>
}
else if (shipments.Count == 0)
{
    <p>No shipments found.</p>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Estimated Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in shipments)
            {
                <tr>
                    <td>@shipment.TrackingNumber</td>
                    <td>@shipment.Destination</td>
                    <td>@shipment.Status</td>
                    <td>@shipment.EstimatedDelivery.ToShortDateString()</td>
                    <td>
                        <select class="form-select form-select-sm d-inline-block w-auto"
                                value="@shipment.Status"
                                @onchange="(e) => UpdateStatus(shipment.Id, e.Value?.ToString() ?? shipment.Status)">
                            <option value="Pending">Pending</option>
                            <option value="InTransit">InTransit</option>
                            <option value="Delivered">Delivered</option>
                            <option value="Delayed">Delayed</option>
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<Shipment>? shipments;
    private bool showForm;
    private Shipment newShipment = new() { ShippedDate = DateTime.Today, EstimatedDelivery = DateTime.Today.AddDays(5), Status = "Pending" };

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private void ToggleForm() => showForm = !showForm;

    private async Task CreateShipment()
    {
        await ShipmentService.CreateShipmentAsync(newShipment);
        newShipment = new() { ShippedDate = DateTime.Today, EstimatedDelivery = DateTime.Today.AddDays(5), Status = "Pending" };
        showForm = false;
        await LoadShipments();
    }

    private async Task UpdateStatus(int id, string status)
    {
        await ShipmentService.UpdateShipmentStatusAsync(id, status);
        await LoadShipments();
    }
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>

<div class="row mb-3">
    <div class="col-md-6">
        <div class="input-group">
            <input class="form-control" placeholder="Enter tracking number" @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment">Track</button>
        </div>
    </div>
</div>

@if (searched && shipment is null)
{
    <div class="alert alert-warning">
        No shipment found with tracking number "<strong>@searchedNumber</strong>". Please check the number and try again.
    </div>
}

@if (shipment is not null)
{
    <div class="card">
        <div class="card-header">
            <h5 class="mb-0">Shipment: @shipment.TrackingNumber</h5>
        </div>
        <div class="card-body">
            <dl class="row mb-0">
                <dt class="col-sm-4">Status</dt>
                <dd class="col-sm-8"><span class="badge bg-@GetStatusColor(shipment.Status)">@shipment.Status</span></dd>

                <dt class="col-sm-4">Origin</dt>
                <dd class="col-sm-8">@shipment.Origin</dd>

                <dt class="col-sm-4">Destination</dt>
                <dd class="col-sm-8">@shipment.Destination</dd>

                <dt class="col-sm-4">Shipped Date</dt>
                <dd class="col-sm-8">@shipment.ShippedDate.ToShortDateString()</dd>

                <dt class="col-sm-4">Estimated Delivery</dt>
                <dd class="col-sm-8">@shipment.EstimatedDelivery.ToShortDateString()</dd>

                @if (shipment.ActualDelivery.HasValue)
                {
                    <dt class="col-sm-4">Actual Delivery</dt>
                    <dd class="col-sm-8">@shipment.ActualDelivery.Value.ToShortDateString()</dd>
                }

                <dt class="col-sm-4">Description</dt>
                <dd class="col-sm-8">@shipment.Description</dd>
            </dl>
        </div>
    </div>
}

@code {
    private string trackingNumber = string.Empty;
    private string searchedNumber = string.Empty;
    private Shipment? shipment;
    private bool searched;

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        searchedNumber = trackingNumber;
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber);
        searched = true;
    }

    private async Task HandleKeyDown(Microsoft.AspNetCore.Components.Web.KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private static string GetStatusColor(string status) => status switch
    {
        "Pending" => "secondary",
        "InTransit" => "primary",
        "Delivered" => "success",
        "Delayed" => "warning",
        _ => "info"
    };
}

